*, *::before, *::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

:root {
  /* Warm amber-gold palette */
  --gold-100: #fffbf0;
  --gold-200: #fef3c7;
  --gold-300: #fcd34d;
  --gold-400: #f59e0b;
  --gold-500: #d97706;
  --gold-600: #b45309;
  --amber-deep: #78350f;
  --ember:      #92400e;

  --text-primary:   #1c0a00;
  --text-secondary: #6b3a12;
  --text-muted:     #a16207;

  --surface:        rgba(255, 251, 240, 0.6);
  --surface-solid:  #fffbf0;

  --border: rgba(245, 158, 11, 0.25);

  --font-display: Georgia, "Times New Roman", serif;
  --font-body:    -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, "Helvetica Neue", Arial, sans-serif;

  --transition: 200ms ease;
}

html, body, #root {
  height: 100%;
  overflow: hidden;
}

body {
  font-family: var(--font-body);
  color: var(--text-primary);
  background: var(--gold-100);
  /* Radial warm glow behind center */
  background-image:
    radial-gradient(ellipse 60% 70% at 50% 50%, rgba(251, 191, 36, 0.18) 0%, transparent 70%),
    radial-gradient(ellipse 100% 100% at 50% -10%, rgba(245, 158, 11, 0.12) 0%, transparent 60%);
}

/* ── Layout grid ────────────────────────────────────── */
.viewport {
  display: grid;
  grid-template-columns: 200px 1fr 200px;
  height: 100vh;
  max-width: 1280px;
  margin: 0 auto;
  padding: 0 2rem;
}

/* ── Left column ────────────────────────────────────── */
.left-col {
  display: flex;
  flex-direction: column;
  justify-content: space-between;
  align-items: flex-start;
  padding: 3rem 1.5rem 3rem 0;
